import MockDate from 'mockdate'
import moment from 'moment-timezone'
import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

beforeEach(() => { MockDate.set(new Date()) })
afterEach(() => { MockDate.reset() })

const NY = 'America/New_York'

describe('Convert', () => {
  it('format Z', () => {
    const d = dayjs().tz(NY)
    expect(d.format('Z')).toBe(moment().tz(NY).format('Z'))
    expect(d.format('ZZ')).toBe(moment().tz(NY).format('ZZ'))
    expect(d.format('Z')).toMatch(/^[+-]\d{2}:\d{2}$/)
    expect(d.format('ZZ')).toMatch(/^[+-]\d{4}$/)
  })

  it('format Z literal', () => {
    expect(dayjs().tz('Asia/Kolkata').format('Z')).toBe('+05:30')
    expect(dayjs().tz('Asia/Kolkata').format('ZZ')).toBe('+0530')
    expect(dayjs().tz('UTC').format('Z')).toBe('+00:00')
    expect(dayjs().tz('UTC').format('ZZ')).toBe('+0000')
  })

  it('format Z with milliseconds', () => {
    const d = dayjs('2020-01-01T00:00:00.500Z').tz(NY)
    expect(d.format('Z')).toBe('-05:00')
    expect(d.format('ZZ')).toBe('-0500')
  })
})
EOF
